import{_ as n,o as t,c as s,a0 as e}from"./chunks/framework.BpJS36ta.js";const h=JSON.parse('{"title":"Const","description":"","frontmatter":{},"headers":[],"relativePath":"syntax/const.md","filePath":"syntax/const.md"}'),i={name:"syntax/const.md"};function o(r,a,d,l,c,p){return t(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="const" tabindex="-1">Const <a class="header-anchor" href="#const" aria-label="Permalink to &quot;Const&quot;">​</a></h1><h2 id="apa-yang-bisa-ditulis" tabindex="-1">Apa yang bisa ditulis? <a class="header-anchor" href="#apa-yang-bisa-ditulis" aria-label="Permalink to &quot;Apa yang bisa ditulis?&quot;">​</a></h2><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const x: number = 1</span></span>
<span class="line"><span>const y = x + 2</span></span></code></pre></div><p><code>const</code> adalah keyword sebelum assignment. Dengan atau tanpa anotasi tipe keduanya valid.</p><h2 id="kapan-digunakan" tabindex="-1">Kapan digunakan? <a class="header-anchor" href="#kapan-digunakan" aria-label="Permalink to &quot;Kapan digunakan?&quot;">​</a></h2><p>Gunakan <code>const</code> untuk binding yang tidak boleh di-reassign setelah inisialisasi — konstanta, nilai yang dihitung sekali, atau invariant.</p><h2 id="apa-hasilnya" tabindex="-1">Apa hasilnya? <a class="header-anchor" href="#apa-hasilnya" aria-label="Permalink to &quot;Apa hasilnya?&quot;">​</a></h2><p><code>const</code> adalah properti <strong>slot/binding</strong>, bukan properti nilai:</p><ul><li>Deklarasi <code>const x = v</code> menulis <strong>dan mengunci</strong> slot <code>x</code>.</li><li>Assignment biasa (<code>x = ...</code>) ke slot terkunci ditolak saat eksekusi mencapai store tersebut — statement sebelum tetap berjalan normal.</li><li>Deklarasi const di dalam loop / fungsi <strong>re-init sah</strong> di setiap iterasi atau call (slot lama di-reset, lalu dikunci ulang).</li></ul><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const x: number = 1</span></span>
<span class="line"><span>print(x)   # 1</span></span>
<span class="line"><span>x = 10     # ConstError: cannot reassign const variable &#39;x&#39;</span></span></code></pre></div><h2 id="pesan-error" tabindex="-1">Pesan error <a class="header-anchor" href="#pesan-error" aria-label="Permalink to &quot;Pesan error&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error</th><th>Kondisi</th></tr></thead><tbody><tr><td><code>ConstError</code></td><td>Assignment biasa ke binding yang sudah const-locked</td></tr><tr><td><code>TypeError</code></td><td>Anotasi tipe setelah <code>const</code> tidak cocok dengan nilai</td></tr></tbody></table>`,12)])])}const g=n(i,[["render",o]]);export{h as __pageData,g as default};
